SELECT count(cupom_id) AS n
FROM pedido
WHERE status = 'pago' AND cupom_id IS NOT NULL;

WITH cte AS (
  SELECT id, nome FROM cliente WHERE uf IN ('RS', 'SC')
)
SELECT id, nome FROM cte;

